utf-8.pseudocode:
def utf8_encode_cp(cp):
    if cp <= 0x7F:
        return [cp]  # ASCII 1바이트
    elif cp <= 0x7FF:
        return [0xC0 | (cp >> 6),
                0x80 | (cp & 0x3F)]
    elif cp <= 0xFFFF:  # 한글 등 3바이트
        return [0xE0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3F),
                0x80 | (cp & 0x3F)]
    else:  # 보충 평면 4바이트
        return [0xF0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3F),
                0x80 | ((cp >> 6) & 0x3F),
                0x80 | (cp & 0x3F)]
